@tailwind base;
@tailwind components;
@tailwind utilities;

/* ============================================================================
 * Dobeu Design System v2 — CSS variables
 * Mirror of @dobeu/tokens (see C:/Users/jswil/dobeu-eco/figma-design/dobeu-design-system/packages/tokens)
 * Values are HSL components (no hsl() wrapper) so Tailwind's `hsl(var(--x))` works.
 * Brand colors (indigo) NEVER change across themes. Only accent + active motif shift per property.
 * ============================================================================ */

@layer base {
  :root {
    /* ---- Raw Dobeu palette (HSL) ----
       Indigo 500 = #6B5CE7  → hsl(249, 73%, 63%)
       Indigo 700 = #4A3FA8  → hsl(247, 46%, 45%)
       Amber 500  = #F4A261  → hsl(27, 88%, 67%)
       Ink 900    = #1A1A2E  → hsl(240, 28%, 14%)
       Paper 50   = #FAFAFC  → hsl(240, 22%, 99%) */

    --dobeu-indigo-50: 249 80% 96%;
    --dobeu-indigo-100: 249 78% 92%;
    --dobeu-indigo-200: 249 76% 84%;
    --dobeu-indigo-300: 249 74% 76%;
    --dobeu-indigo-400: 249 73% 68%;
    --dobeu-indigo-500: 249 73% 63%;
    --dobeu-indigo-600: 248 60% 56%;
    --dobeu-indigo-700: 247 46% 45%;
    --dobeu-indigo-800: 246 40% 35%;
    --dobeu-indigo-900: 245 38% 26%;

    --dobeu-amber-500: 27 88% 67%;
    --dobeu-amber-600: 22 70% 58%;

    --dobeu-ink-900: 240 28% 14%;
    --dobeu-paper-50: 240 22% 99%;

    /* ---- v2 brand primitives (Design System v2) ---- */
    /* Indigo Slate #5A4FAB — wordmark color + light-mode heading color */
    --brand-indigo-slate: 247 38% 49%;
    /* Cream Soft #FFF8F0 — light-mode secondary surface */
    --brand-cream-soft: 36 100% 97%;
    /* Borders */
    --brand-border-light: 247 60% 92%; /* #E0DFF5 */
    --brand-border-dark: 245 24% 22%; /* #2A2A45 */
    /* 10% tints (for badges, pills, soft fills) */
    --brand-tint-indigo-10: 250 70% 95%; /* #E8E5FA */
    --brand-tint-amber-10: 30 90% 94%; /* #FEF0E0 */
    /* Heading-specific foreground (slate by default in light mode) */
    --fg-heading: var(--brand-indigo-slate);

    /* ---- Light theme (default for dobeu.net) ---- */
    --background: 0 0% 100%; /* pure white per brand canvas spec */
    --foreground: var(--dobeu-ink-900);

    --card: 0 0% 100%;
    --card-foreground: var(--dobeu-ink-900);

    --popover: 0 0% 100%;
    --popover-foreground: var(--dobeu-ink-900);

    --primary: var(--dobeu-indigo-500);
    --primary-foreground: var(--dobeu-paper-50);

    --secondary: var(--brand-cream-soft);
    --secondary-foreground: var(--dobeu-ink-900);

    --accent: var(--dobeu-amber-500);
    --accent-foreground: var(--dobeu-ink-900);

    --muted: 240 10% 96%;
    --muted-foreground: 240 6% 40%;

    --destructive: 0 75% 55%;
    --destructive-foreground: 0 0% 100%;

    --border: var(--brand-border-light);
    --input: var(--brand-border-light);
    --ring: var(--dobeu-indigo-500);

    --radius-sm: 6px;
    --radius-md: 12px; /* v2: buttons + inputs land at 12px */
    --radius-lg: 20px; /* v2: cards land at 20px */
    --radius-xl: 24px;
    --radius-pill: 999px;

    /* Elevated surface — slightly above background, used for cards/dropdowns */
    --elevated: 0 0% 100%; /* light: same as card */
  }

  .dark {
    --background: var(--dobeu-ink-900);
    --foreground: var(--dobeu-paper-50);

    /* Heading slate doesn't read on dark surfaces — fall back to paper */
    --fg-heading: var(--dobeu-paper-50);

    --card: 240 25% 18%;
    --card-foreground: var(--dobeu-paper-50);

    --popover: 240 25% 16%;
    --popover-foreground: var(--dobeu-paper-50);

    /* v2 CTA-swap rule: in dark mode the primary CTA flips to amber. */
    --primary: var(--dobeu-amber-500);
    --primary-foreground: var(--dobeu-ink-900);

    --secondary: 240 20% 22%;
    --secondary-foreground: var(--dobeu-paper-50);

    --accent: var(--dobeu-indigo-400);
    --accent-foreground: var(--dobeu-ink-900);

    --muted: 240 20% 22%;
    --muted-foreground: 240 8% 70%;

    --destructive: 0 65% 50%;
    --destructive-foreground: 0 0% 100%;

    --border: var(--brand-border-dark);
    --input: var(--brand-border-dark);
    --ring: var(--dobeu-amber-500);

    /* Elevated surface — dark: #242440 as per Dobeu brand spec */
    --elevated: 240 25% 18%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    scroll-behavior: smooth;
  }
  body {
    @apply bg-background text-foreground font-sans;
    font-feature-settings:
      "rlig" 1,
      "calt" 1,
      "ss01" 1;
  }
  /* Focus ring — accent-colored, high contrast */
  :focus-visible {
    @apply outline-none ring-2 ring-ring ring-offset-2 ring-offset-background;
  }
  /* Selection */
  ::selection {
    background-color: hsl(var(--primary) / 0.25);
    color: hsl(var(--foreground));
  }
  /* Reduce motion respectfully — WCAG 2.1 SC 2.3.3
   *
   * Two-layer fix:
   * 1. Kill animation / transition timing for CSS-driven motion.
   * 2. Force opacity to 1 on any element that uses Framer Motion's inline
   *    `style="opacity:0"` initial state — without this the element stays
   *    invisible because JS `animation-duration` collapse happens after the
   *    initial render flush. The `useMotionProps` hook is the primary fix;
   *    this CSS rule is a belt-and-suspenders fallback for any missed sites.
   */
  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
    /* Reveal any element whose opacity was set to 0 by a JS animation engine */
    [style*="opacity: 0"],
    [style*="opacity:0"] {
      opacity: 1 !important;
    }
  }
}

/* ---- Utility extensions ---- */
@layer utilities {
  .gradient-text {
    @apply bg-gradient-to-r from-dobeu-indigo-500 to-dobeu-amber-500 bg-clip-text text-transparent;
  }
  .gradient-text-deep {
    background: linear-gradient(
      135deg,
      hsl(var(--primary)) 0%,
      hsl(var(--accent)) 100%
    );
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
  }
  .glass {
    @apply bg-background/70 backdrop-blur-xl backdrop-saturate-150 border border-border/60;
  }
  .skip-link {
    @apply sr-only focus:not-sr-only focus:absolute focus:top-2 focus:left-2 focus:z-50 focus:rounded focus:bg-background focus:px-3 focus:py-2 focus:text-sm focus:shadow-lg;
  }
  /* Hide scrollbars on overflow containers (SubBrandsStrip ticker row) */
  .scrollbar-none {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
  .scrollbar-none::-webkit-scrollbar {
    display: none;
  }
}

