            .from("invoices")
            .update({ hosted_invoice_url: inv.hosted_invoice_url })
            .eq("stripe_invoice_id", inv.id);
        }
        break;
      }

      case "invoice.voided": {
        const inv = event.data.object as Stripe.Invoice;
        if (inv.id) {
