            .from("invoices")
            .update({ status: "void" })
            .eq("stripe_invoice_id", inv.id);
        }
        break;
      }

      default:
        console.log(
          JSON.stringify({
            msg: "stripe_webhook_ignored",
            request_id: requestId,
            event_id: event.id,
            event_type: event.type
          })
        );
        break;
    }
  } catch (e) {
    console.error(
      JSON.stringify({
        msg: "stripe_webhook_handler_error",
        request_id: requestId,
        event_id: event.id,
        event_type: event.type,
        error: e instanceof Error ? e.message : String(e)
      })
    );
