/** Lightweight non-crypto hash to avoid storing raw IPs in lead payloads. */
export function hashIp(ip: string): string {
  let h = 0;
  for (let i = 0; i < ip.length; i++) h = ((h << 5) - h + ip.charCodeAt(i)) | 0;
  return `ip_${Math.abs(h).toString(36)}`;
